function kikiState(t,i){ const th=0.18*Math.sin(t*(t>=14&&t<16.5?3.4:2.2)); const hx=KIKI_ANCHOR+KIKI_LEN*Math.sin(th), hy=KIKI_LEN*Math.cos(th);
  if(t<16.5) return {mode:'hang',hx,hy,x:hx,y:hy+150,dir:1,point:Math.min(seg(t,7.8,8.1),1-seg(t,9.0,9.3))};
  const p=kikiPerch(t,i); if(t<17.6){ const u=easeInOut(seg(t,16.5,17.6)); return {mode:'jump',x:lerp(hx,p.x,u),y:lerp(hy+150,p.y-42,u)-160*Math.sin(Math.PI*u),dir:-1,point:0}; }
  return {mode:'sit',x:p.x,y:p.y-42,dir:-1,point:0}; }

/* ---------- Tuki, der Tukan ---------- */
function toucan(x,y,dir,t,fly){ ctx.save(); ctx.translate(x,y); ctx.scale(dir,1); const flap=fly?0.7*Math.sin(t*14):0.1;
  ctx.fillStyle='#212121'; ctx.save(); ctx.translate(-6,-6); ctx.rotate(-flap); ctx.beginPath(); ctx.ellipse(-30,0,40,14,0.2,0,6.29); ctx.fill(); ctx.restore();
  ctx.beginPath(); ctx.ellipse(0,0,26,40,0,0,6.29); ctx.fill(); ctx.fillStyle='#FFF3B0'; ctx.beginPath(); ctx.ellipse(8,-4,15,26,0,0,6.29); ctx.fill(); ctx.fillStyle='#212121'; ctx.beginPath(); ctx.moveTo(-12,30); ctx.lineTo(-30,60); ctx.lineTo(4,44); ctx.closePath(); ctx.fill(); ctx.fillStyle='#C62828'; ctx.beginPath(); ctx.ellipse(0,32,12,8,0,0,6.29); ctx.fill();
  dots([[4,-34,22]],'#212121'); ctx.fillStyle='#FFB300'; ctx.beginPath(); ctx.moveTo(18,-48); ctx.quadraticCurveTo(70,-52,92,-30); ctx.lineTo(80,-18); ctx.quadraticCurveTo(50,-18,18,-24); ctx.closePath(); ctx.fill(); ctx.fillStyle='#F57C00'; ctx.beginPath(); ctx.moveTo(70,-46); ctx.quadraticCurveTo(84,-40,92,-30); ctx.lineTo(80,-18); ctx.lineTo(66,-22); ctx.closePath(); ctx.fill(); ctx.strokeStyle='#212121'; ctx.lineWidth=2; ctx.beginPath(); ctx.moveTo(20,-30); ctx.quadraticCurveTo(50,-30,80,-22); ctx.stroke();
  dots([[6,-40,10]],'#4FC3F7'); dots([[6,-40,7]],'#FFF'); dots([[8,-40,3.5]],'#111'); ctx.save(); ctx.translate(-2,-6); ctx.rotate(flap); ctx.fillStyle='#111'; ctx.beginPath(); ctx.ellipse(-28,4,38,13,0.25,0,6.29); ctx.fill(); ctx.restore(); if(!fly){ ctx.strokeStyle='#F57C00'; ctx.lineWidth=4; ctx.beginPath(); ctx.moveTo(-8,38); ctx.lineTo(-10,52); ctx.moveTo(8,38); ctx.lineTo(10,52); ctx.stroke(); } ctx.restore(); }
function tukiState(t,i){ if(t>=4.9&&t<6.2){ const u=seg(t,4.9,6.2); return {x:lerp(1200,-140,u),y:250+16*Math.sin(t*6),dir:-1,fly:true}; }
  if(t<14.0) return null; const mx=mountX(t); if(t<16.5){ const u=easeOut(seg(t,14.0,14.6)); return {x:lerp(1250,mx+380,u)+10*Math.sin(t*3),y:lerp(300,330,u)+12*Math.sin(t*4),dir:1,fly:true}; }
  const off=SCX_END-SCX[i]; const px=785+off, py=GROUND_Y-340; if(t<17.6){ const u=easeInOut(seg(t,16.5,17.6)); return {x:lerp(mountX(16.5)+380,px,u),y:lerp(330,py,u)-60*Math.sin(Math.PI*u),dir:1,fly:true}; }
  return {x:px,y:py+2*Math.sin(t*2),dir:1,fly:false}; }

/* ---------- Texte ---------- */
function texts(t,i,kk){ const name=nameVal();
  if(t<3){ text('Lager-Eröffnung: Die Forscher-Crew bricht auf …',W/2,H*.14,fitFont('Lager-Eröffnung: Die Forscher-Crew bricht auf …',W-100,60,38,700),'#F3F0E4','center','#0F3D1C',9); }
  popIn(t,3.0,4.8,W/2,H*.22,()=>text('EXPEDITION, LOS!',0,0,fitFont('EXPEDITION, LOS!',W-120,170,80),'#FFFFFF','center','#0F3D1C',26));
  if(t>=6.3&&t<9.4){ const u=easeOut(seg(t,6.3,6.9)); const s1=`${name} auf Spurensuche!`; ctx.save(); ctx.globalAlpha=u*(1-seg(t,8.9,9.4)); ctx.translate(lerp(-300,0,u),0); text(s1,W/2,H*.11,fitFont(s1,W-140,112,64),'#FFFFFF','center','#0F3D1C',24); ctx.restore(); }
  if(t>=9.9&&t<11.4){ ctx.save(); ctx.globalAlpha=Math.min(seg(t,9.9,10.2),1-seg(t,11.0,11.4)); text('Achtung, Tiger!',W/2,H*.13,fitFont('Achtung, Tiger!',W-100,110,70),'#FFD54F','center','#0F3D1C',22); ctx.restore(); }
  popIn(t,10.9,11.7,W/2+120,H*.23,()=>text('GRRRR!',0,0,fontB(140),'#F57C00','center','#0F3D1C',22));
  popIn(t,14.3,16.2,W/2,H*.78,()=>text('Zum Wasserfall!',0,0,fitFont('Zum Wasserfall!',W-120,120,64),'#FFFFFF','center','#0F3D1C',26));
  if(kk&&kk.mode==='hang'){ if(t>=8.0&&t<9.2) bubble(kk.hx-360,kk.hy-220,400,110,'Da lang, Forscher!',Math.min(seg(t,8.0,8.3),1-seg(t,8.9,9.2)),'#1B5E20','#FFD54F',true); if(t>=13.2&&t<14.3) bubble(kk.hx-360,kk.hy-220,400,110,'Der zeigt den Weg!',Math.min(seg(t,13.2,13.5),1-seg(t,14.0,14.3)),'#1B5E20','#FFD54F',true); }
  if(t>=12.4&&t<13.4) bubble(640,820,340,110,'Party?!',Math.min(seg(t,12.4,12.7),1-seg(t,13.1,13.4)),'#C65D00','#FFD54F',true);
  popIn(t,20.2,20.9,995,950,()=>text('Huch!',0,0,fontB(50),'#FFD54F','center','#0F3D1C',14));
  if(t>=20.5){ const u=easeOutBack(seg(t,20.5,21.2)); const cardW=W-140, cardH=520, x=70, y=lerp(-620,40,u); ctx.save(); ctx.shadowColor='rgba(0,0,0,.45)'; ctx.shadowBlur=36; ctx.shadowOffsetY=14; ctx.fillStyle='#E8DCC0'; rrect(x,y,cardW,cardH,18); ctx.fill(); ctx.restore(); ctx.strokeStyle='#2E7D32'; ctx.lineWidth=6; rrect(x+14,y+14,cardW-28,cardH-28,12); ctx.stroke(); ctx.fillStyle='#66BB6A'; for(const [lx,ly,r] of [[x+22,y+22,0.8],[x+cardW-22,y+22,2.3],[x+22,y+cardH-22,-0.8],[x+cardW-22,y+cardH-22,-2.3]]){ ctx.save(); ctx.translate(lx,ly); ctx.rotate(r); ctx.beginPath(); ctx.ellipse(0,-22,12,26,0,0,6.29); ctx.fill(); ctx.beginPath(); ctx.ellipse(18,-12,12,26,0.9,0,6.29); ctx.fill(); ctx.restore(); }
    ctx.fillStyle='#C8B27A'; rrect(x+30,y-18,300,40,10); ctx.fill(); text('FORSCHUNGS-LIZENZ',x+180,y+2,fontD(24,700),'#3E2723');
    ctx.save(); ctx.translate(x+cardW-130,y+cardH-70); ctx.rotate(-0.22); ctx.globalAlpha=0.85; ctx.strokeStyle='#C65D00'; ctx.lineWidth=6; rrect(-120,-30,240,60,8); ctx.stroke(); text('GENEHMIGT',12,2,fontB(34,800),'#C65D00'); dots([[-90,4,11],[-104,-12,5],[-92,-16,5],[-80,-13,5],[-70,-4,4]],'#C65D00'); ctx.restore();
    const title=`🌴 ${possName(name)} Dschungel-Party`; text(title,W/2,y+112,fitFont(title,cardW-140,74,44),'#1B5E20'); text(`📅 ${$('date').value}  ·  ${$('time').value}`,W/2,y+215,fontD(54),'#3E2723'); const pl=wrap(`📍 ${$('place').value}`,cardW-120,fontD(54)); pl.forEach((ln,k)=>text(ln,W/2,y+296+k*62,fontD(54),'#3E2723'));
    const pulse=1+.04*Math.sin(t*6); ctx.save(); ctx.translate(W/2-110,y+440); ctx.scale(pulse,pulse); text('🐒 Kommst du mit?',0,0,fontB(74),'#C65D00'); ctx.restore(); }
  ctx.globalAlpha=.6; text('machsleicht.de',W/2,H-42,fontD(38,600),'#FFFFFF'); ctx.globalAlpha=1; }

function shakeAmp(t){ let a=0; if(t>=10.9&&t<11.7) a=Math.max(a,4*Math.sin(seg(t,10.9,11.7)*Math.PI)); if(t>=14.0&&t<16.6) a=Math.max(a,2); if(t>=18.4&&t<18.8) a=Math.max(a,4*(1-seg(t,18.4,18.8))); if(t>=19.2&&t<19.6) a=Math.max(a,5*(1-seg(t,19.2,19.6))); return a; }

/* ---------- Frame ---------- */
function drawFrame(i){ i=clamp(i,0,P_N-1); const t=i/FPS; const a=shakeAmp(t);
  sky(t);
  ctx.save(); if(a>0){ ctx.translate(SHAKE[i][0]*a,SHAKE[i][1]*a); }
  hills(i); keep(i,t); trees(i); lianas(i,t); ground(i,t); camp(i,t); lager(i,t);
  { const off=SCX_END-SCX[i]; if(off<W+400){ ctx.save(); ctx.translate(off,0); tiger(775,GROUND_Y,-1,'sit',0,1,false,0,true); ctx.restore(); } }   /* Tamu als Schatz-Waechter */
  mount(t,i);
  const d=tamuState(t); if(d) tiger(d.x,d.y,1,d.run?'run':'stand',t*14,d.hdir,d.roar,d.blush,d.happy);
  const kk=kikiState(t,i); if(kk.mode==='hang'){ ctx.strokeStyle='#33691E'; ctx.lineWidth=9; ctx.lineCap='round'; ctx.beginPath(); ctx.moveTo(KIKI_ANCHOR,-10); ctx.quadraticCurveTo(KIKI_ANCHOR+(kk.hx-KIKI_ANCHOR)*0.4,kk.hy*0.5,kk.hx,kk.hy-150); ctx.stroke(); dots([[KIKI_ANCHOR+(kk.hx-KIKI_ANCHOR)*0.5,kk.hy*0.5,12]],'#4CAF50'); } monkey(kk.x,kk.y,kk.dir,t,kk.mode==='hang'?'hang':'sit',kk.point);
  const tk=tukiState(t,i); if(tk) toucan(tk.x,tk.y,tk.dir,t,tk.fly);
  if(t>=20.2){ const hp=hatPos(t,i); helm(hp.x,hp.y,hp.rot,1); }
  bigLeaves(i); streaks(i,t); partyConfetti(t,CHEST.x+75,CHEST.y,19.3,2.8);
  ctx.restore();
  texts(t,i,kk); }

/* ---------- Ton ---------- */
function audio(ac,master,S){ const {tone,noise,bell,bed,env}=S;
  const drum=(t0,peak=0.5)=>{ tone(t0,150,80,0.28,'sine',peak,0.003,0.22); noise(t0,0.08,'lowpass',500,200,0.25,0.002,0.06); };
  const brass=(t0,f,dur,peak=0.2)=>{ const o=ac.createOscillator(); o.type='sawtooth'; o.frequency.value=f; const fl=ac.createBiquadFilter(); fl.type='lowpass'; fl.frequency.setValueAtTime(600,t0); fl.frequency.linearRampToValueAtTime(2400,t0+0.08); fl.frequency.linearRampToValueAtTime(1200,t0+dur); const g=ac.createGain(); env(g,t0,0.03,peak,Math.max(0.01,dur-0.13),0.1); o.connect(fl).connect(g).connect(master); o.start(t0); o.stop(t0+dur+0.3); };
  const trumpet=(t0,dur,peak=0.22)=>{ const o=ac.createOscillator(); o.type='sawtooth'; o.frequency.setValueAtTime(260,t0); o.frequency.linearRampToValueAtTime(520,t0+dur*0.35); o.frequency.linearRampToValueAtTime(420,t0+dur); const v=ac.createOscillator(); v.frequency.value=9; const vg=ac.createGain(); vg.gain.value=18; v.connect(vg).connect(o.frequency); const fl=ac.createBiquadFilter(); fl.type='lowpass'; fl.frequency.value=1500; const g=ac.createGain(); env(g,t0,0.05,peak,dur-0.2,0.15); o.connect(fl).connect(g).connect(master); o.start(t0); v.start(t0); o.stop(t0+dur+0.3); v.stop(t0+dur+0.3); };
  const squawk=(t0)=>{ tone(t0,1100,700,0.09,'square',0.07,0.005,0.05); tone(t0+0.12,1000,650,0.09,'square',0.07,0.005,0.05); };
  const chatter=(t0,n)=>{ for(let k=0;k<n;k++) tone(t0+k*0.07,1400+(k%3)*250,1700+(k%2)*200,0.05,'square',0.05,0.003,0.03); };
  const step=(t0)=>{ tone(t0,70,48,0.14,'sine',0.32,0.003,0.1); noise(t0,0.06,'lowpass',300,150,0.12,0.002,0.05); };
  drum(0.6); drum(1.3); drum(2.0); squawk(2.4); bell(3.0,1568,0.22); noise(3.0,0.5,'lowpass',400,200,0.2,0.05,0.4);                    /* Trommeln, Tukan, Ding, Ottilie schnauft */
  for(let t=3.4;t<10.6;t+=0.37) step(t); for(let t=14.2;t<17.6;t+=0.26) step(t);                                                     /* Elefantenschritte */
  bed('bandpass',600,0.8,[[3.4,0],[4,0.03],[10.4,0.03],[10.8,0],[14.0,0],[14.6,0.05],[17.4,0.05],[17.8,0]],0,0);                    /* Blaetterrascheln */
  squawk(5.2); squawk(5.7); chatter(7.0,6); chatter(8.05,5);                                                                            /* Tuki, Kiki */
  for(let t=9.6;t<10.8;t+=0.11) noise(t,0.05,'lowpass',400,200,0.14,0.003,0.04); noise(10.75,0.3,'bandpass',500,250,0.14,0.02,0.2);   /* Tamu tapst, stoppt */
  tone(10.9,85,70,0.8,'sawtooth',0.28,0.03,0.5); noise(10.9,0.8,'lowpass',260,140,0.3,0.03,0.5); trumpet(11.15,0.6,0.2);            /* GRRRR, Ottilie trompetet erschrocken */
  tone(12.4,500,700,0.2,'sine',0.15,0.01,0.1); tone(12.65,700,950,0.25,'sine',0.15,0.01,0.12); [12.9,13.02,13.14].forEach((t,k)=>tone(t,420+k*100,420+k*100,0.08,'square',0.08,0.005,0.05)); chatter(13.25,6);
  for(let t=13.3;t<13.9;t+=0.09) noise(t,0.05,'lowpass',400,200,0.14,0.003,0.04);                                                     /* Tamu rennt voraus */
  noise(14.0,0.6,'bandpass',300,1400,0.14,0.05,0.35); bed('bandpass',900,0.6,[[13.9,0],[14.6,0.14],[16.4,0.14],[17.4,0]],0.8,0.05); squawk(14.5); squawk(15.6);   /* Vollgas, Wind */
  bed('lowpass',700,0.7,[[16.3,0],[17.5,0.12],[24,0.12]],0.4,0.03); noise(17.6,0.5,'lowpass',500,250,0.18,0.02,0.35);                  /* Wasserfall-Rauschen, Ottilie stoppt */
  /* Kiste knacken */ tone(18.42,900,600,0.08,'square',0.12,0.002,0.05); noise(18.45,0.35,'bandpass',700,300,0.16,0.02,0.25); tone(18.5,180,140,0.35,'sawtooth',0.05,0.02,0.2); [18.7,18.85,19.0].forEach((t,k)=>bell(t,[1568,1976,2349][k],0.24)); { const r=S.rng(9); for(let k=0;k<8;k++){ const f=2400+r()*1800; tone(18.7+r()*0.7,f,f,0.12,'sine',0.06,0.005,0.1); } }
  /* Fanfare, Konfetti, Fontaene, Helm, Kiki */ drum(19.2,0.5); drum(19.4,0.5); [[19.5,392],[19.7,494],[19.9,587]].forEach(([t,f])=>brass(t,f,0.28,0.2)); brass(20.15,784,0.8,0.18); noise(19.3,0.35,'lowpass',700,300,0.5,0.003,0.25); trumpet(19.45,1.1,0.24); noise(19.7,1.3,'bandpass',1400,1400,0.09,0.1,0.6); { const r=S.rng(13); for(let k=0;k<12;k++){ const f=1800+r()*2200; tone(19.5+r()*2.0,f,f,0.12,'sine',0.05,0.005,0.1); } }
  noise(20.2,0.2,'bandpass',600,1400,0.18,0.01,0.1); tone(20.9,240,160,0.12,'sine',0.2,0.005,0.08); chatter(21.0,5); squawk(20.6); bell(20.7,1046,0.22);
  for(const f of [392,494,587]) for(const d of [-5,5]){ const o=ac.createOscillator(); o.type='sawtooth'; o.frequency.value=f+d; const fl=ac.createBiquadFilter(); fl.type='lowpass'; fl.frequency.value=1200; const g=ac.createGain(); env(g,20.0,0.8,0.018,2.6,0.6); o.connect(fl).connect(g).connect(master); o.start(20.0); o.stop(24); } }

